"""Generate Lexer observations and digit tables from the frozen Python 3.12 Oracle."""

from decimal import Decimal
from hashlib import sha256
from pathlib import Path
import sys
import unicodedata


def utf8(text: str) -> str:
    return text.encode("utf-8").hex() or "-"


def value_field(text: str) -> str:
    # Compare long boundary lexemes and values without duplicating them in the fixture.
    content = text.encode("utf-8")
    return "sha256:" + sha256(content).hexdigest() if len(content) > 256 else utf8(text)


def position(pos) -> str:
    return f"{pos.offset},{pos.line},{pos.column}"


def diagnostic_position(source: str, location) -> str:
    lines = source.split("\n")
    offset = sum(len(line) + 1 for line in lines[:location.line - 1]) + location.column - 1
    return f"{offset},{location.line},{location.column}"


def digit_tables() -> None:
    assert unicodedata.unidata_version == "15.0.0"
    zeroes = []
    other_edges = []
    previous = False
    for codepoint in range(128, 0x110000):
        character = chr(codepoint)
        if unicodedata.decimal(character, -1) == 0:
            zeroes.append(codepoint)
        other_digit = character.isdigit() and not character.isdecimal()
        if other_digit != previous:
            other_edges.append(codepoint)
        previous = other_digit
    assert not previous
    print("// Generated by tests/fixtures/generate_lexer.py (Python 3.12, Unicode 15.0).")
    for comment, name, values in (
        ("Starting code points of the non-ASCII decimal digit sets.", "DECIMAL_ZEROES", zeroes),
        ("Half-open boundaries for isdigit() characters outside those sets.",
         "OTHER_DIGIT_BOUNDARIES", other_edges),
    ):
        print(f"\n// {comment}\n#[rustfmt::skip]\nconst {name}: &[u32] = &[")
        for start in range(0, len(values), 10):
            print("    " + ", ".join(f"0x{value:x}" for value in values[start:start + 10]) + ",")
        print("];")


def fixture(oracle: Path) -> None:
    sys.path.insert(0, str(oracle.resolve()))
    from nsl.diagnostics import CompileError
    from nsl.source import SourceFile
    from nsl.syntax import Lexer, SourceLanguageVersion

    assert sys.get_int_max_str_digits() == 4300
    lex = Lexer()
    print("# Python Oracle 28a949ec96581cbdc52c8133527b23bb5b72ee0a")
    common = [
        ("empty", ""),
        ("keywords", "language skill version description risk include requires limits input context "
                     "output tool let read foreach in max check assert severity on_fail message emit "
                     "write approve approved_by Write writer approve_ approved_by2"),
        ("booleans", "true false True False true_ _false"),
        ("symbols", "{}():;,.=+-*/<> <= >= == != <== !== >== /= // <> ignored\n+"),
        ("numbers", "0 01 9.0 032.050 1. .5 17.2ms 7.² ².٣ ³ ① ١٢ 1e3 -0"),
        ("duration_units", "0ms 0003ms 020s 4m 1msX 2s_ 3m2 2MS ๑๒s １２ms 𑽑𑽒m 7sé"),
        ("duration_eof_boundary", "1ms"),
        ("duration_unicode_boundary", "2s² 3m\u0301"),
        ("multiline", '// 주석😀\r\n"예산😀e\u0301"\r\nabc\t"\n한\r\n끝"\r"줄\u2028나눔"'),
        ("escapes", r'"" "a\n\r\t\"\\\q\한" ' + '"\\\n"'),
        ("comments", "/ // / <= trailing comment\rignore\n//\tend"),
        ("recover_unexpected", "한글 @ \r🙂\nabc ! $ ^\ttrue"),
        ("not_python_digit", "½ Ⅷ ㊿"),
        ("unterminated_string", 'write "한글\n  '),
        ("unterminated_escape", '"한글\n\\'),
        ("unexpected_then_unterminated", '@ "x'),
        ("bad_duration_digit", "²s"),
        ("fatal_after_diagnostic", "@ ②ms write"),
    ]
    long_cases = [
        ("duration_4300", "9", 4300, "ms"),
        ("duration_4301", "9", 4301, "ms"),
        ("minutes_4300", "9", 4300, "m"),
        ("leading_zeros_4301", "0", 4301, "s"),
        ("unicode_duration_4300", "９", 4300, "s"),
        ("mixed_invalid_precedence", "9", 4301, "²ms"),
        ("plain_4301", "9", 4301, ""),
    ]

    def emit(label, mode, version, prefix, unit="", repeat=0, tail=""):
        text = prefix + unit * repeat + tail
        source = SourceFile.from_text("lexer/fixture.ns", text)
        print("case", label, mode, version, utf8(prefix), utf8(unit), repeat, utf8(tail),
              source.source_id, sep="\t")
        try:
            if mode == "root":
                tokens = lex.tokenize_root(source)
                diagnostics = ()
            else:
                result = lex.scan(source, version)
                tokens, diagnostics = result.tokens, result.diagnostics
        except CompileError as error:
            print("root_error", error.code, diagnostic_position(text, error.location), sep="\t")
            return
        except ValueError as error:
            message = str(error)
            if message.startswith("Exceeds the limit"):
                kind = "too_many_digits"
            else:
                assert message.startswith("invalid literal for int()")
                kind = "non_decimal_digit"
            print("duration_error", kind, sep="\t")
            return
        for item in tokens:
            if type(item.value) is bool:
                value_kind, value = "bool", str(item.value).lower()
            elif type(item.value) is int:
                value_kind, value = "milliseconds", format(Decimal(item.value), "f")
            else:
                value_kind, value = "text", item.value
            print("token", item.kind.value, value_kind, value_field(value), value_field(item.lexeme),
                  position(item.span.start), position(item.span.end), sep="\t")
        for diagnostic in diagnostics:
            print("diag", diagnostic.code.value, diagnostic_position(text, diagnostic.location), sep="\t")

    for version in SourceLanguageVersion:
        for label, text in common:
            emit(label, "scan", version, text)
        for label, unit, repeat, tail in long_cases:
            emit(label, "scan", version, "", unit, repeat, tail)
        for label, body in (("root_keywords", "write approve approved_by"),
                            ("root_unexpected", "write @"), ("root_bad_duration", "²s")):
            emit(label, "root", version, f'// 예산\nlanguage NSL "{version}"; {body}')
    emit("root_bad_header", "root", "-", 'language NSL "0.3"; write')
    emit("root_missing_header", "root", "-", "skill write")


if __name__ == "__main__":
    if sys.argv[1] == "--digit-tables":
        digit_tables()
    else:
        fixture(Path(sys.argv[1]))
